import{_ as i,C as a,o as n,c as h,j as d,a as e,E as o,a5 as c}from"./chunks/framework.Dep_XxFZ.js";const g=JSON.parse('{"title":"滚动区域","description":"","frontmatter":{},"headers":[],"relativePath":"components/scroll-area.md","filePath":"components/scroll-area.md","lastUpdated":1787363843000}'),s={name:"components/scroll-area.md"},b={id:"滚动区域",tabindex:"-1"};function p(u,t,m,f,x,P){const l=a("Badge"),r=a("XhDemo");return n(),h("div",null,[d("h1",b,[t[0]||(t[0]=e("滚动区域 ",-1)),o(l,{type:"info",text:"scroll-area"}),t[1]||(t[1]=e()),t[2]||(t[2]=d("a",{class:"header-anchor",href:"#滚动区域","aria-label":'Permalink to "滚动区域 <Badge type="info" text="scroll-area" />"'},"​",-1))]),t[3]||(t[3]=c('<p>给一块溢出的内容配一条外观受控的滚动条。滚动本身走的是浏览器原生通路，组件只画滚动条。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>滚动条的外观要跟站点一致（各平台的原生滚动条长得很不一样）。</li><li>需要控制滚动条什么时候露面。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>整页滚动：交给浏览器，别套。</li><li>内容是长列表且条数很多：用<a href="./virtualizer">虚拟滚动</a>，只画滚动条解决不了渲染量。</li><li>滚到底要继续加载：用<a href="./infinite-scroll">无限滚动</a>。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li>它是视口加两条<a href="./scrollbar">滚动条</a>的组装：<code>scrollbar</code> 挂载点同时是那条滚动条的根，里面照滚动条的写法摆轨道、滑块与交叉口；显隐、拖动、几何全是滚动条那一套。</li><li><code>root</code> 要有确定高度，视口才量得出溢出。</li><li><code>type</code> 决定滚动条什么时候露面：<code>hover</code> 指针进来才露，<code>auto</code> 溢出就露，<code>always</code> 恒露，<code>scroll</code> 滚动时露、停手后收起。</li><li><code>orientation</code> 关掉的那条轴滚动条恒不显形，视口那一向也不再滚，不留滚不回来的暗格。</li><li><code>dir</code> 必须显式给：组件不读计算样式，看不见从 RTL 祖先继承来的方向。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>root 要有确定高度，视口才量得出溢出；滚动走的是浏览器原生通路，组件只画滚动条</p>',10)),o(r,{src:"scroll-area/01-basic"}),t[4]||(t[4]=d("h3",{id:"显隐时机",tabindex:"-1"},[e("显隐时机 "),d("a",{class:"header-anchor",href:"#显隐时机","aria-label":'Permalink to "显隐时机"'},"​")],-1)),t[5]||(t[5]=d("p",null,"type 决定滚动条什么时候露面：hover 指针进来才露，always 恒露，scroll 滚动时露、停手后收起",-1)),o(r,{src:"scroll-area/02-type"}),t[6]||(t[6]=d("h3",{id:"双轴与拐角",tabindex:"-1"},[e("双轴与拐角 "),d("a",{class:"header-anchor",href:"#双轴与拐角","aria-label":'Permalink to "双轴与拐角"'},"​")],-1)),t[7]||(t[7]=d("p",null,"两条轴各写一条滚动条，corner 补上右下角那块空白；内容要比视口宽，横轴才量得出溢出",-1)),o(r,{src:"scroll-area/03-both-axes"}),t[8]||(t[8]=d("h3",{id:"只管一条轴",tabindex:"-1"},[e("只管一条轴 "),d("a",{class:"header-anchor",href:"#只管一条轴","aria-label":'Permalink to "只管一条轴"'},"​")],-1)),t[9]||(t[9]=d("p",null,"orientation 关掉的那条轴滚动条恒不显形，视口那一向也不再滚，不留滚不回来的暗格",-1)),o(r,{src:"scroll-area/04-orientation"}),t[10]||(t[10]=d("h3",{id:"收起的等待",tabindex:"-1"},[e("收起的等待 "),d("a",{class:"header-anchor",href:"#收起的等待","aria-label":'Permalink to "收起的等待"'},"​")],-1)),t[11]||(t[11]=d("p",null,"type 为 scroll 时滚动条停手后不立刻收起，hideDelay 决定还留多少毫秒",-1)),o(r,{src:"scroll-area/05-hide-delay"}),t[12]||(t[12]=c('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-scroll-area&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhScrollAreaContent</code> <code>XhScrollAreaCorner</code> <code>XhScrollAreaRoot</code> <code>XhScrollAreaScrollbar</code> <code>XhScrollAreaThumb</code> <code>XhScrollAreaTrack</code> <code>XhScrollAreaViewport</code></td></tr><tr><td>组合式函数</td><td><code>useScrollArea</code></td></tr><tr><td>状态机</td><td>无，<code>connect</code> 直接由 props 算属性</td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/scroll-area.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;scroll-area&quot;</code>：<strong><code>root</code></strong> · <strong><code>viewport</code></strong> · <strong><code>content</code></strong> · <code>scrollbar</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>dir</code></td><td><code>Direction</code></td><td></td><td>排版方向，默认随文档。只影响横轴：RTL 下滚动量的正负、指针位移的方向都要翻一次。 必须显式给：组件不读计算样式，看不见从 RTL 祖先继承来的方向。</td></tr><tr><td><code>forceVisible</code></td><td><code>boolean</code></td><td></td><td>触屏（粗指针）上也画自绘滚动条，默认 false：缺省交给原生滚动。</td></tr><tr><td><code>hideDelay</code></td><td><code>number</code></td><td></td><td>收起前的等待毫秒（type 为 scroll / hover 时生效），默认 600。</td></tr><tr><td><code>orientation</code></td><td><code>ScrollAreaOrientation</code></td><td></td><td>哪几条轴归本组件管，默认 both。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg，换的是滚动条厚度。</td></tr><tr><td><code>type</code></td><td><code>ScrollbarType</code></td><td></td><td>滚动条露面的时机，默认 hover。</td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhScrollAreaRoot</code></td><td><code>default</code></td><td><code>ScrollAreaRootSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>scrollbar</code></td><td>&#39;visible&#39; | &#39;hidden&#39;</td></tr><tr><td><code>corner</code></td><td>&#39;visible&#39; | &#39;hidden&#39;</td></tr></tbody></table><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useScrollArea</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>type</code></td><td><code>ScrollbarType</code></td><td></td></tr><tr><td><code>orientation</code></td><td><code>ScrollAreaOrientation</code></td><td></td></tr><tr><td><code>vertical</code></td><td><code>ScrollAreaAxisState</code></td><td></td></tr><tr><td><code>horizontal</code></td><td><code>ScrollAreaAxisState</code></td><td></td></tr><tr><td><code>draggingAxis</code></td><td><code>Orientation | null</code></td><td>正被拖动的那条轴；没在拖为 null。</td></tr><tr><td><code>cornerVisible</code></td><td><code>boolean</code></td><td>右下角补丁该不该显形：两条滚动条同时在场才有它的位置。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getViewportProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getContentProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getScrollbarProps</code></td><td><code>(props: ScrollAreaScrollbarProps) =&gt; T[&#39;element&#39;]</code></td><td>某条轴的滚动条挂载点，同时充当那条 scrollbar 的根节点。</td></tr><tr><td><code>getTrackProps</code></td><td><code>(props: ScrollAreaScrollbarProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getThumbProps</code></td><td><code>(props: ScrollAreaScrollbarProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getCornerProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td>交叉口补丁，写在竖条的挂载点里；只有两条都在场时才显形。</td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/WCAG21/Techniques/general/G202" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>焦点走到滚动区</td><td>视口带 tabindex=0，键盘用户能停在滚动区上；组件只在这一处动过 Tab 序列</td></tr><tr><td><code>PageUp</code> / <code>PageDown</code></td><td>focus in viewport</td><td>按视口高度翻页滚动；组件不监听、不拦截</td></tr><tr><td><code>ArrowUp</code> / <code>ArrowDown</code> / <code>ArrowLeft</code> / <code>ArrowRight</code></td><td>focus in viewport</td><td>逐行/逐列滚动；组件不监听、不拦截</td></tr><tr><td><code>Home</code> / <code>End</code></td><td>focus in viewport</td><td>滚到内容两端；组件不监听、不拦截</td></tr><tr><td><code>Space</code> / <code>Shift+Space</code></td><td>focus in viewport</td><td>整屏翻页；组件不监听、不拦截</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>scrollbar</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/scroll-area.css</code> 按部件选择：<code>[data-scope=&quot;scroll-area&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-dragging</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-orientation</code></td><td>props.orientation</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-type</code></td><td>props.type</td></tr><tr><td><code>viewport</code></td><td><code>data-lane-horizontal</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>viewport</code></td><td><code>data-lane-vertical</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>viewport</code></td><td><code>data-native</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>viewport</code></td><td><code>data-orientation</code></td><td>props.orientation</td></tr><tr><td><code>content</code></td><td><code>data-orientation</code></td><td>props.orientation</td></tr><tr><td><code>scrollbar</code></td><td><code>data-dragging</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>scrollbar</code></td><td><code>data-gutter</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>scrollbar</code></td><td><code>data-native</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>scrollbar</code></td><td><code>data-orientation</code></td><td>axis</td></tr><tr><td><code>scrollbar</code></td><td><code>data-scrolling</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>scrollbar</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>scrollbar</code></td><td><code>data-state</code></td><td>&#39;visible&#39; | &#39;hidden&#39;</td></tr><tr><td><code>scrollbar</code></td><td><code>data-type</code></td><td>props.type</td></tr><tr><td><code>corner</code></td><td><code>data-state</code></td><td>&#39;visible&#39; | &#39;hidden&#39;</td></tr></tbody></table><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>状态切换走 <code>transition</code>。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>放进<a href="./splitter">分栏</a>的面板、<a href="./dialog">对话框</a>的内容区、<a href="./menu">菜单</a>的长条目列表。</li><li>把<a href="./table">表格</a>放进视口：表格不再自己定高与滚，吸顶表头与吸附列钉在视口上，两条滚动条照常工作。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>触屏（粗指针）上默认交给原生滚动、不画自绘滚动条；<code>forceVisible</code> 打开才画，那时别用 <code>hover</code>：那里没有悬停。</li><li>内容可滚时给出可见提示（渐隐边缘或恒显滚动条），否则用户不知道下面还有东西。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>把 <code>root</code> 的高度留给内容撑：量不出溢出，滚动条永远不出现。</li><li>用它包住整页，再在里面嵌套多层滚动区域：滚轮落在哪一层不可预期。</li></ul>',38))])}const S=i(s,[["render",p]]);export{g as __pageData,S as default};
